  @Inject
  FixedTokenLookupGateway tokenLookupGateway;
  @Inject
  ScenarioPasswordRecoveryMailGateway passwordRecoveryMailGateway;
  @Inject
  ScenarioUserRegistrationMailGateway userRegistrationMailGateway;
  @Inject
  TokenSigner tokenSigner;
  @Inject
  JwtTokenBuilder tokenBuilder;

  @BeforeEach
  void resetState() {
    sessionStore.clear();
    temporalKeysGateway.clear();
    clientStoreGateway.reset();
    loginGateway.reset();
    consentGateway.reset();
    mfaGateway.reset();
    changePasswordGateway.reset();
    scopeConsentGateway.reset();
    registerGateway.reset();
    delegateGateway.reset();
    tokenLookupGateway.clear();
    passwordRecoveryMailGateway.reset();
    userRegistrationMailGateway.reset();
  }

  protected Map<String, Object> decodeToken(String token) {
    return tokenSigner.verifyTokenPayload(OidcTestFixtures.TENANT, token);
  }

  protected List<String> claimAsList(Object value) {
    if (value == null) {
      return List.of();
    }
    if (value instanceof List<?>) {
      List<?> list = (List<?>) value;
      List<String> result = new ArrayList<>();
      for (Object item : list) {
        result.add(String.valueOf(item));
      }
      return result;
    }
    if (value instanceof String[]) {
      return List.of((String[]) value);
    }
    String str = String.valueOf(value);
    return str.isBlank() ? List.of() : List.of(str);
  }

  protected void assertTokenScopes(String token, List<String> expected) {
    Map<String, Object> payload = decodeToken(token);
    Assertions.assertFalse(payload.isEmpty());
    List<String> scopes = claimAsList(payload.get("scope"));
    Assertions.assertEquals(expected, scopes);
  }

  protected ChallengesState decodeChallenge(String cookie) {
    Optional<ChallengesState> challenge =
        tokenBuilder.verifyChalleger(ChallengesState.class, cookie, OidcTestFixtures.TENANT);
    Assertions.assertTrue(challenge.isPresent());
    return challenge.get();
  }
